True from collections import deque
def transform(grid):
    h,w=len(grid),len(grid[0]); bg=grid[0][0]
    seen=set(); out=[row[:] for row in grid]
    for r in range(h):
      for c in range(w):
        if grid[r][c]!=bg or (r,c) in seen: continue
        q=deque([(r,c)]); seen.add((r,c)); comp=[]; edge=False
        while q:
          x,y=q.popleft(); comp.append((x,y)); edge |= x==0 or y==0 or x==h-1 or y==w-1
          for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
            a,b=x+dx,y+dy
            if 0<=a<h and 0<=b<w and grid[a][b]==bg and (a,b) not in seen: seen.add((a,b)); q.append((a,b))
        if not edge:
          rs=[x for x,y in comp]; cs=[y for x,y in comp]
          color=2 if (max(rs)-min(rs)+1)%2==0 and (max(cs)-min(cs)+1)%2==0 else 7
          for x,y in comp: out[x][y]=color
    return out
